232	    }
233	
234	    /**
235	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
236	     * offending field is collected so the caller learns exactly which values must be supplied.
237	     *
238	     * @param ownerFieldsDto the submitted owner payload
239	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
240	     *         telephone is missing or blank
241	     */
242	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
243	        List<String> missingFields = new ArrayList<>();
244	        if (isBlank(ownerFieldsDto.getFirstName())) {
245	            missingFields.add("firstName");
246	        }
247	        if (isBlank(ownerFieldsDto.getLastName())) {
248	            missingFields.add("lastName");
249	        }
250	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
251	            missingFields.add("address");
252	        }
253	        if (isBlank(ownerFieldsDto.getCity())) {
254	            missingFields.add("city");
255	        }
256	        if (isBlank(ownerFieldsDto.getTelephone())) {
257	            missingFields.add("telephone");
258	        }
259	        if (!missingFields.isEmpty()) {
260	            throw new MissingOwnerFieldsException(missingFields);
261	        }
262	    }
263	
264	    private boolean isBlank(String value) {
265	        return value == null || value.isBlank();
266	    }
267	
268	    /**
269	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
270	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
271	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
272	     *
273	     * @param lastName the owner's last name
274	     * @return the formatted customer code
275	     */
276	    private String generateCustomerCode(String lastName) {
277	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
278	        int sequence = this.clinicService.findAllOwners().size() + 1;
279	        return String.format("%s-%04d", last3, sequence);
280	    }
281	
282	    /**
283	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
284	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
285	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
286	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
287	     * stored and returned.
288	     *
289	     * @param telephone the raw telephone value from the request
290	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
291	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
292	     */
293	    private String normalizeTelephone(String telephone) {
294	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
295	        String e164;
296	        if (cleaned.startsWith("+")) {
297	            e164 = cleaned;
298	        } else {
299	            String national = cleaned;
300	            if (national.startsWith("0")) {
301	                national = national.substring(1);
302	            }
303	            e164 = "+61" + national;
304	        }
305	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
306	            throw new InvalidOwnerFieldsException(List.of("telephone"));
307	        }
308	        return e164;
309	    }
310	
311	    /**
312	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
313	     * left unset. When a value is present it must be a syntactically valid address; the normalized
314	     * form stored and returned is the value lower-cased.
315	     *
316	     * @param email the raw email value from the request, or {@code null} when none was supplied
317	     * @return the lower-cased email, or {@code null} when no email was supplied
318	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
319	     */
320	    private String normalizeEmail(String email) {
321	        if (email == null || email.isBlank()) {
322	            return null;
323	        }
324	        if (!EMAIL_PATTERN.matcher(email).matches()) {
325	            throw new InvalidOwnerFieldsException(List.of("email"));
326	        }
327	        return email.toLowerCase(Locale.ROOT);
328	    }
329	
330	    /**
331	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
332	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
333	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
334	     * normalized form is what gets stored, returned and used for every address comparison (the
335	     * required-field check, household duplicate detection and the shared household id).
336	     *
337	     * @param address the raw address value from the request, or {@code null}
338	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
339	     */
340	    private String normalizeAddress(String address) {
341	        if (address == null) {
342	            return "";
343	        }
344	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
345	        if (collapsed.isEmpty()) {
346	            return "";
347	        }
348	        String[] tokens = collapsed.split(" ");
349	        for (int i = 0; i < tokens.length; i++) {
350	            switch (tokens[i]) {
351	                case "ST" -> tokens[i] = "STREET";
352	                case "RD" -> tokens[i] = "ROAD";
353	                case "AVE" -> tokens[i] = "AVENUE";
354	                default -> { }
355	            }
356	        }
357	        return String.join(" ", tokens);
358	    }
359	
360	    /**
361	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
362	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
363	     * directly and is therefore independent of the punctuation a caller supplied.
364	     *
365	     * @param e164Telephone the E.164 telephone of the owner being created
366	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
367	     */
368	    private void rejectDuplicateTelephone(String e164Telephone) {
369	        boolean inUse = this.clinicService.findAllOwners().stream()
370	            .map(Owner::getTelephone)
371	            .filter(existing -> existing != null)
372	            .anyMatch(e164Telephone::equals);
373	        if (inUse) {
374	            throw new DuplicateOwnerTelephoneException(e164Telephone);
375	        }
376	    }
377	
378	    /**
379	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
380	     * last name and a normalized address: last names are compared case-insensitively after whitespace
381	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
382	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
383	     * abbreviation still count as the same household.
384	     * <p>
385	     * When the owner's last name and address already belong to at least one other owner the behaviour
386	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
387	     * household. If it is true the create is allowed and every member of the household - the existing
388	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
389	     * read. When no other owner shares the last name and address no identifier is assigned.
390	     *
391	     * @param owner the owner being created
392	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
393	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
394	     *         address and {@code sharesHousehold} is not true
395	     */
396	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
397	        String lastName = normalizeHouseholdField(owner.getLastName());
398	        String address = normalizeAddress(owner.getAddress());
399	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
400	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
401	                && normalizeAddress(existing.getAddress()).equals(address))
402	            .toList();
403	        if (housemates.isEmpty()) {
404	            return;
405	        }
406	        if (!Boolean.TRUE.equals(sharesHousehold)) {
407	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
408	        }
409	        String householdId = generateHouseholdId(lastName, address);
410	        owner.setHouseholdId(householdId);
411	        for (Owner housemate : housemates) {
412	            if (!householdId.equals(housemate.getHouseholdId())) {
413	                housemate.setHouseholdId(householdId);
414	                this.clinicService.saveOwner(housemate);
415	            }
416	        }
417	    }
418	
419	    /**
420	     * Builds the stable identifier shared by the members of one household. It is derived purely from
421	     * the normalized last name and address, so every owner of a given household deterministically
422	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
423	     * two normalized fields joined by a single space.
424	     *
425	     * @param normalizedLastName the household's last name, already normalized for comparison
426	     * @param normalizedAddress the household's address, already normalized for comparison
427	     * @return the shared household identifier
428	     */
429	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
430	        String key = normalizedLastName + '�' + normalizedAddress;
431	        try {
432	            byte[] digest = MessageDigest.getInstance("SHA-256")
433	                .digest(key.getBytes(StandardCharsets.UTF_8));
434	            StringBuilder hex = new StringBuilder();
435	            for (byte b : digest) {
436	                hex.append(String.format("%02X", b));
437	                if (hex.length() >= 12) {
438	                    break;
439	                }
440	            }
441	            return hex.substring(0, 12);
442	        } catch (NoSuchAlgorithmException e) {
443	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
444	        }
445	    }
446	
447	    /**
448	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
449	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
450	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
451	     * expands common abbreviations.
452	     *
453	     * @param value the raw last name, or {@code null}
454	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
455	     */
456	    private String normalizeHouseholdField(String value) {
457	        if (value == null) {
458	            return "";
459	        }
460	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
461	    }
462	}
